Set Variable [ $r ; Value: MBS( "List.AndColumn"; 
"1 test 3¶a b c¶d¶e f"; 
"2 test 4¶a f c¶d b"; 
" "; 1 ) ]

Set Variable [ $r ; Value: Let(
	[
		// you have a list
		list = "132430¶132433¶132437¶132445¶132447¶132450¶132463¶132464¶132465¶132466¶132468¶132469¶132470¶";

		// find a value
		index = MBS( "List.IndexOfFirstValueMatching"; list; "="; 132450; 1);

		// now pick one after it:
		nextValue = MBS( "List.GetValue"; List; index + 1)
	];
	nextValue
) ]

Set Variable [ $r ; Value: MBS("Plugin.RegisterFunction"; 7; "ConcatJS"; "ConcatJS(Value1; Value2)"; "function ConcatJS(a, b) {
  return String(a) + String(b);
}"; 2; 2; 1) ]

Set Variable [ $r ; Value: MBS( "Plugin.RegisterFunction"; 11; "TestCounterWK()"; "function TestCounterWK() {
  globalThis.counter = (globalThis.counter || 0) + 1;
  return globalThis.counter;
}"; 0; 0; 2 + 4) ]

Set Variable [ $r ; Value: MBS( "Plugin.RegisterScriptStep"; 
// internal ID. Must be unique 
123; 
// name of script step
"Concat"; 
// XML definition of parameters
"<PluginStep>
	<Parameter Type=\"target\" Label=\"Destination\" ShowInLine=\"true\"/>
	<Parameter Type=\"calc\" DataType=\"text\" ShowInline=\"true\"  Label=\"FirstName\"  ID=\"0\"/>
	<Parameter Type=\"calc\" DataType=\"text\" ShowInline=\"true\"  Label=\"SecondName\" ID=\"1\"/>
</PluginStep>";
// calculation 
"MBS(\"Plugin.ScriptStepParameter\"; 0) & MBS(\"Plugin.ScriptStepParameter\"; 1)"; 
// description
"Concat two texts" ) ]

Set Variable [ $r ; Value: MBS("Math.BitWiseAnd"; MBS( "Preferences.GetValue"; "com.filemaker.client.pro12"; "Preferences:AppGenOptions"); 8)

// for FileMaker Pro 17 on MacOS:

// Value is 8 for custom name.
// Value is 0 for system name. ]

Set Variable [ $r ; Value: Let ( [

// read current options
~currentValue = MBS( "Preferences.GetValue"; ""; "Preferences:AppGenOptions");

// make sure 4th bit is set by setting bit for 8:
~newValue = MBS("Math.BitwiseOR"; ~currentValue; 8);

// and save back value
~result = MBS( "Preferences.SetValue"; ""; "Preferences:AppGenOptions"; ~newValue; "integer")

]; ~result) ]

Set Variable [ $r ; Value: Let(
[
oldValue = MBS( "Preferences.GetValue"; "com.filemaker.client.pro12"; "Preferences:AppGenOptions");
newValue = MBS("Math.BitWiseOr"; oldValue; 32 + 32768);
R = MBS( "Preferences.SetValue"; "com.filemaker.client.pro12"; "Preferences:AppGenOptions"; newValue; "integer")
];r ) ]

Set Variable [ $r ; Value: Let([
  session = MBS( "Translation.StartSession"; "de"; "en");
  text = MBS( "Translation.TranslateString"; session; "Hallo Leute");
  r = MBS("Translation.Release"; session)
]; text) ]

Set Variable [ $r ; Value: Let([
  session = MBS( "Translation.StartSession"; "de"; "en");
  json = "[]";
  json = JSONSetElement ( json ; "[+].sourceText" ; "Hallo Leute" ; JSONString );
  json = JSONSetElement ( json ; "[+].sourceText" ; "Man sieht sich bei der Konferenz!" ; JSONString );
  text = MBS( "Translation.Translations"; session; json);
  r = MBS("Translation.Release"; session)
]; text) ]

Set Variable [ $r ; Value: Let([
  session = MBS( "Translation.StartSession"; "de"; "en");
  json = "[]";
  json = JSONSetElement ( json ; "[+].sourceText" ; "Hallo Leute" ; JSONString );
  json = JSONSetElement ( json ; "[:].clientIdentifier" ; "1" ; JSONString );
  json = JSONSetElement ( json ; "[+].sourceText" ; "Man sieht sich bei der Konferenz!" ; JSONString );
  json = JSONSetElement ( json ; "[:].clientIdentifier" ; "2" ; JSONString );
  text = MBS( "Translation.Translations"; session; json);
  r = MBS("Translation.Release"; session)
]; text) ]
